# 2. NEUROBIOLOGICAL CIRCUIT REPRESENTATION (BRAIN STATES)

@dataclass
class BrainState:
    # Evidence quality generated by dorsolateral prefrontal cortex (dlPFC)
    dlPFC_signal: float

    # Cognitive effort and conflict estimated by dorsomedial prefrontal cortex (dmPFC)
    dmPFC_effort: float

    # Precision of attentional and oculomotor circuits (Superior Colliculus)
    SC_precision: float

    # Response caution mediated by pre-SMA and basal ganglia circuits
    preSMA_caution: float

    # Additional motor preparation latency due to Frontal Eye Fields (FEF) conflict
    FEF_conflict: float


# ------------------------------------------------------------------------------
# Clinical Phenotype Profiles
# ------------------------------------------------------------------------------

# 1. Healthy Control Cohort (Standard balance)
control_state = BrainState(
    dlPFC_signal=0.30,
    dmPFC_effort=0.02,
    SC_precision=1.20,
    preSMA_caution=0.10,
    FEF_conflict=0.05,
)

# 2. Impulsive ADHD Cohort (Reduced boundary caution, attenuated evidence accumulation)
impulsive_state = BrainState(
    dlPFC_signal=0.22,
    dmPFC_effort=0.04,
    SC_precision=1.00,
    preSMA_caution=0.08,
    FEF_conflict=0.05,
)

# 3. Adult Compensatory ADHD Cohort (Mowinckel et al. findings: elevated boundary to offset lower drift)
compensatory_state = BrainState(
    dlPFC_signal=0.20,
    dmPFC_effort=0.05,
    SC_precision=0.95,
    preSMA_caution=0.14,
    FEF_conflict=0.08,
)
